@Composable
fun AvatarImage(
    url: String,
    username: String?,
    modifier: Modifier = Modifier,
    size: Dp = 40.dp,
) {
    val navigator = LocalNavigator.current
    SubcomposeAsyncImage(
        model = url,
        contentDescription = "Avatar",
        modifier = modifier
            .size(size)
            .clip(CircleShape)
            .clickable {
                username?.apply {
                    navigator.navigate("person/$this")
